import { calculateFarmingRate } from '../engines/farming.js';
import { calculateMonsterRewards } from '../engines/reward.js';
import { powerAt } from '../engines/progression.js';
import { esc, fmt, heading, panel, table, card, pct, status } from './common.js';

export function renderEconomy(c,page){
 if(page==='maps') return renderMaps(c);
 if(page==='boss-rewards') return renderBossRewards(c);
 if(page==='gold') return renderGold(c);
 if(page==='farming') return renderFarming(c);
 return renderRewards(c);
}
function renderRewards(c){
 const rows=c.monsters.slice().sort((a,b)=>a.level-b.level).map(m=>{
  const power=powerAt(m.level,c.config.powerCurve,'normal');const farm=calculateFarmingRate({monster:m,profile:{effectiveDps:power},config:c.config});const r=calculateMonsterRewards({monster:m,killsPerHour:farm.killsPerHour,baseShare:c.config.partyShare});
  return `<tr><td>${esc(m.name)}<small class="source-flag"> · ${m.id}</small></td><td>${m.level}</td><td>${fmt(m.stats.hp,0)}</td><td>${fmt(m.rewards.baseExp,0)}</td><td>${fmt(m.rewards.jobExp,0)}</td><td>${fmt((m.rewards.goldMin+m.rewards.goldMax)/2,2)}</td><td>${fmt(r.baseExpPerHour,0)}</td><td>${fmt(r.jobExpPerHour,0)}</td><td>${fmt(r.goldPerHour,0)}</td><td>${fmt(r.expPer1000Hp,2)}</td><td>${farm.source==='Theoretical; spawn data unavailable'?status('WARNING','Theoretical'):status('PASS','Spawn limited')}</td></tr>`;
 });
 const recommendation=c.config.syncMode==='auto-rewards'?panel('Recommended Monster Rewards · preview only','<div class="toolbar"><span class="tag proposed">Current EXP table remains locked</span><button class="button primary" data-action="preview-rewards">Preview & Apply Recommended Base EXP</button></div>'+table(['Monster ID','Monster','Active Base EXP','Recommended Base EXP'],[...c.recommendedRewards.entries()].map(([id,value])=>{const m=c.monsters.find(x=>String(x.id)===id);return '<tr><td>'+id+'</td><td>'+esc(m?.name||'—')+'</td><td>'+fmt(m?.rewards.baseExp,0)+'</td><td>'+fmt(value,0)+'</td></tr>'}))):'';
 return heading('Monster Rewards','Reward/hour derives from active rewards and TTK-based theoretical or spawn-limited farming. Bosses stay outside normal leveling baselines by default.')+recommendation+panel('Reward efficiency by monster',table(['Monster / ID','Lv','HP','Base EXP/kill','Job EXP/kill','Average Gold/kill','Base EXP/hr','Job EXP/hr','Gold/hr','Base EXP / 1k HP','Rate evidence'],rows));
}
function renderFarming(c){
 const m=c.monsters.find(x=>String(x.id)===String(c.ui.monsterId))||c.monsters.find(x=>!x.boss),power=Number(c.ui.farmDps||powerAt(m.level,c.config.powerCurve,'normal'));
 const config={...c.config,manualMode:c.ui.farmMode==='manual',manualKillsPerMinute:Number(c.ui.manualKpm||10),spawnModel:c.ui.spawnModel||c.config.spawnModel,spawnCapacityOverride:Number(c.ui.spawnCapacity||0),farmingUptime:Number(c.ui.farmingUptime??c.config.farmingUptime)};
 const farm=calculateFarmingRate({monster:m,profile:{effectiveDps:power},config,aoe:c.ui.aoeEnabled?{enabled:true,effectiveTargets:Number(c.ui.aoeTargets||3),groupingSeconds:Number(c.ui.groupingSeconds||1),castingInterval:Number(c.ui.castingInterval||2),aggregateDps:Number(c.ui.aggregateAoeDps||power)}:null});
 const rewards=calculateMonsterRewards({monster:m,killsPerHour:farm.killsPerHour,baseShare:c.config.partyShare});
 return `${heading('Farming Efficiency','TTK + movement + target acquisition + looting + combat overhead. Manual mode preserves measured kill rates.')}${panel('Farming model inputs',`<div class="form-grid"><label class="field">Monster<select class="control" data-ui="monsterId">${c.monsters.filter(x=>!x.boss).map(x=>`<option value="${x.id}" ${String(x.id)===String(m.id)?'selected':''}>${esc(x.name)} · Lv ${x.level}</option>`).join('')}</select></label><label class="field">Effective DPS<input class="control" data-ui="farmDps" type="number" min="0" value="${power}"></label><label class="field">Rate model<select class="control" data-ui="farmMode"><option value="theoretical" ${config.manualMode?'':'selected'}>TTK / theoretical</option><option value="manual" ${config.manualMode?'selected':''}>Manual measured</option></select></label><label class="field">Measured kills/min<input class="control" data-ui="manualKpm" type="number" min="0" value="${config.manualKillsPerMinute}"></label><label class="field">Farming uptime %<input class="control" data-ui="farmingUptime" type="number" min="0" max="100" value="${Math.round(config.farmingUptime*100)}"></label><label class="field">Movement seconds<input class="control" data-config="movementSeconds" type="number" min="0" value="${config.movementSeconds}"></label><label class="field">Acquisition seconds<input class="control" data-config="acquisitionSeconds" type="number" min="0" value="${config.acquisitionSeconds}"></label><label class="field">Looting seconds<input class="control" data-config="lootingSeconds" type="number" min="0" value="${config.lootingSeconds}"></label><label class="field">Combat overhead seconds<input class="control" data-config="combatOverheadSeconds" type="number" min="0" value="${config.combatOverheadSeconds}"></label><label class="field">Spawn model<select class="control" data-ui="spawnModel"><option value="uncapped" ${config.spawnModel==='uncapped'?'selected':''}>Uncapped / unknown</option><option value="independent" ${config.spawnModel==='independent'?'selected':''}>Independent recurring spawn</option></select></label><label class="field">Available spawn cap · kills/hr<input class="control" data-ui="spawnCapacity" type="number" min="0" value="${config.spawnCapacityOverride}"></label><label class="field">Enable AoE group<input type="checkbox" data-ui="aoeEnabled" ${c.ui.aoeEnabled?'checked':''}></label><label class="field">Effective targets/group<input class="control" data-ui="aoeTargets" type="number" min="1" value="${c.ui.aoeTargets||3}"></label><label class="field">Grouping time (sec)<input class="control" data-ui="groupingSeconds" type="number" min="0" value="${c.ui.groupingSeconds||1}"></label><label class="field">Casting interval (sec)<input class="control" data-ui="castingInterval" type="number" min="0" value="${c.ui.castingInterval||2}"></label></div>`)}<div class="grid four" style="margin-top:12px">${card('Combat TTK',`${fmt(m.stats.hp/power,2)} s`,'Direct effective DPS')}${card('Farming cycle',`${fmt(farm.cycleSeconds,2)} s`,'Movement + acquisition + looting + overhead')}${card('Combat capacity',`${fmt(farm.combatKillsPerHour,1)} / hr`,'TTK-derived')}${card('Effective rate',`${fmt(farm.killsPerHour,1)} / hr`,farm.source,farm.warning?'warn':'good')}${card('Base EXP/hour',fmt(rewards.baseExpPerHour,0),'Per-character configured share')}${card('Job EXP/hour',fmt(rewards.jobExpPerHour,0),'Uses active Job EXP reward')}${card('Gold/hour',fmt(rewards.goldPerHour,0),'Arithmetic gold midpoint assumed')}${card('Gold per kill',fmt(rewards.averageGoldPerKill,2),'Uniform midpoint unless configured')}</div><div class="notice-inline">${esc(farm.warning||'Spawn cap is active where supplied.')} ${config.manualMode?'HP changes do not affect the manual measured rate.':''}</div>${farm.aoe?panel('AoE group model',`<div class="metric-line"><span>Targets per group</span><b>${farm.aoe.targetsPerGroup}</b></div><div class="metric-line"><span>Group cycles/hour</span><b>${fmt(farm.aoe.groupCyclesPerHour,1)}</b></div><div class="metric-line"><span>Target kills/hour</span><b>${fmt(farm.aoe.targetKillsPerHour,1)}</b></div><p class="small muted">Aggregate AoE DPS is not multiplied by target count a second time.</p>`):''}`;
}
function renderMaps(c){
 const groups=new Map();for(const m of c.monsters.filter(x=>!x.boss))for(const map of m.maps||[]){const a=groups.get(map.name)||[];a.push(m);groups.set(map.name,a)}
 const rows=[...groups.entries()].map(([name,ms])=>{const calculations=ms.map(m=>{const dps=powerAt(m.level,c.config.powerCurve,'normal');const farm=calculateFarmingRate({monster:m,profile:{effectiveDps:dps},config:c.config});return {m,farm,cycle:Math.max(.001,farm.cycleSeconds||60)}});const avgCycle=calculations.reduce((s,x)=>s+x.cycle,0)/calculations.length;const expectedKills=3600*c.config.farmingUptime/avgCycle;const baseRate=calculations.reduce((s,x)=>s+x.m.rewards.baseExp/avgCycle,0)/calculations.length*3600*c.config.farmingUptime*c.config.partyShare;const jobRate=calculations.reduce((s,x)=>s+x.m.rewards.jobExp/avgCycle,0)/calculations.length*3600*c.config.farmingUptime*c.config.partyShare;const goldRate=calculations.reduce((s,x)=>s+(x.m.rewards.goldMin+x.m.rewards.goldMax)/2/avgCycle,0)/calculations.length*3600*c.config.farmingUptime;return `<tr><td>${esc(name)}</td><td>${ms.length}</td><td>${Math.min(...ms.map(m=>m.level))}–${Math.max(...ms.map(m=>m.level))}</td><td>${fmt(avg(ms.map(m=>m.stats.hp)),0)}</td><td>${fmt(avg(ms.map(m=>m.rewards.baseExp)),0)}</td><td>${fmt(avg(ms.map(m=>m.rewards.jobExp)),0)}</td><td>${fmt(avgCycle,2)} s</td><td>${fmt(expectedKills,1)}</td><td>${fmt(baseRate,0)}</td><td>${fmt(jobRate,0)}</td><td>${fmt(goldRate,0)}</td><td>${status('WARNING','Equal time assumption')}</td></tr>`});
 return `${heading('Map Efficiency','Uses actual monster rows and time-weighted route calculation. Equal-time encounter weighting is labeled where spawn composition is missing.')}${panel('Map farming efficiency',table(['Map','Species','Level range','Median HP','Median Base EXP','Median Job EXP','Expected cycle','Kills/hr','Base EXP/hr','Job EXP/hr','Gold/hr','Weight source'],rows))}<p class="small muted">Map composition weights and spawn counts are absent from the source dataset; this view uses an equal-time share among listed normal monsters, not an observed map rate.</p>`;
}
function renderBossRewards(c){
 const inputs=c.ui.bossOps||{travel:60,respawn:3600,competition:.5,eligible:1,share:.2};
 const bosses=c.monsters.filter(m=>m.boss).map(m=>{const profile=c.store.getState().profiles.combat[0], ttk=m.stats.hp/profile.effectiveDps, interval=Number(inputs.respawn||0), cycle=ttk+Number(inputs.travel||0);const accessible=interval>0?Math.min(3600/cycle,3600/interval):null;const rate=accessible==null?null:accessible*(1-Number(inputs.competition||0))*Number(inputs.eligible||0)*Number(inputs.share||0);return `<tr><td>${esc(m.name)}</td><td>${esc(m.metadata?.tier||'Abyss')}</td><td>${fmt(m.stats.hp,0)}</td><td>${fmt(ttk,2)}s</td><td>${fmt(cycle,1)}s</td><td>${accessible==null?'—':fmt(accessible,2)}</td><td>${rate==null?'—':fmt(rate,2)}</td><td>${rate==null?status('INSUFFICIENT DATA'):status('WARNING','Assumed availability')}</td></tr>`});
 return `${heading('Boss Reward Efficiency','Boss farming is isolated from normal progression and includes noncombat encounter availability.')}${panel('Availability assumptions',`<div class="form-grid"><label class="field">Travel time (seconds)<input class="control" data-bossop="travel" type="number" min="0" value="${inputs.travel}"></label><label class="field">Respawn interval (seconds)<input class="control" data-bossop="respawn" type="number" min="0" value="${inputs.respawn}"></label><label class="field">Competition loss %<input class="control" data-bossop="competition" type="number" min="0" max="100" value="${inputs.competition*100}"></label><label class="field">Reward eligibility share %<input class="control" data-bossop="eligible" type="number" min="0" max="100" value="${inputs.eligible*100}"></label><label class="field">Personal reward allocation %<input class="control" data-bossop="share" type="number" min="0" max="100" value="${inputs.share*100}"></label></div><p class="small muted">Boss reward rates are estimates from editable assumptions; source data does not provide verified competition, eligibility or respawn information.</p>`)}${panel('Boss rate estimates',table(['Boss','Tier','HP','TTK · 2M','Travel + fight','Access/hr','Expected personal reward rate','Evidence'],bosses))}`;
}
function renderGold(c){
 const rows=c.monsters.map(m=>{const dps=powerAt(m.level,c.config.powerCurve,'normal'),farm=calculateFarmingRate({monster:m,profile:{effectiveDps:dps},config:c.config}),r=calculateMonsterRewards({monster:m,killsPerHour:farm.killsPerHour});return {name:m.name,level:m.level,boss:m.boss?'Boss':'Normal',goldMin:m.rewards.goldMin,goldMax:m.rewards.goldMax,average:r.averageGoldPerKill,goldPerHour:r.goldPerHour}}).sort((a,b)=>b.goldPerHour-a.goldPerHour);
 const top='<div class="grid three">'+card('Top modeled gold/hour',fmt(rows[0]?.goldPerHour||0,0),rows[0]?.name||'—')+card('Average gold/kill',fmt(avg(rows.map(x=>x.average)),2),'Arithmetic midpoint')+card('Reward records',rows.length,'No gold sink inferred')+'</div><p class="small muted">Gold distribution shape is not present in monster data. Midpoint assumes a uniform min/max interval. Configure expected value in reward tools when distribution differs.</p>';
 const body=table(['Monster','Level','Category','Gold Min','Gold Max','Expected/kill','Gold/hour'],rows.slice(0,100).map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+x.level+'</td><td>'+x.boss+'</td><td>'+fmt(x.goldMin,0)+'</td><td>'+fmt(x.goldMax,0)+'</td><td>'+fmt(x.average,2)+'</td><td>'+fmt(x.goldPerHour,0)+'</td></tr>'));
 return heading('Gold Economy','Gold faucets use original or edited Gold Min/Max and a stated midpoint assumption.')+panel('Gold production model',top)+panel('Gold by monster',body);
}
function avg(a){return a.length?a.reduce((s,x)=>s+Number(x||0),0)/a.length:0}
